fb.declaration:
FUNCTION_BLOCK FB

VAR_INPUT
    cyclicExecution : BOOL;
    trigger : BOOL;
    value : LREAL;
    windowSize : INT;
    reset : BOOL;
END_VAR
VAR_OUTPUT
    average : LREAL;
    windowSizeReached : BOOL;
    error : BOOL;
    status : WORD;
END_VAR
VAR
    tmp_trig : R_TRIG;
    local_data : ARRAY[0..99] OF LREAL;
    local_count : INT := 0;
    local_start : INT := 0;
    local_sum_all : LREAL := 0.0;
    local_avg_sum : LREAL;
    local_effective : INT;
    tmp_i : INT;
    tmp_idx : INT;
END_VAR

fb.implementation:
tmp_trig(CLK := trigger);

IF reset THEN
    local_count := 0;
    local_start := 0;
    local_sum_all := 0.0;
    average := 0.0;
    windowSizeReached := FALSE;
END_IF;

IF (windowSize < 1) OR (windowSize > 100) THEN
    error := TRUE;
    status := WORD#16#8200;
    windowSizeReached := FALSE;
    average := average; 
ELSE
    error := FALSE;
    status := WORD#16#0000;
END_IF;

IF reset THEN
    average := average; 
END_IF;

IF cyclicExecution THEN
    IF local_count < 100 THEN
        local_data[local_count] := value;
        local_count := local_count + 1;
        local_sum_all := local_sum_all + value;
    ELSE
        local_sum_all := local_sum_all - local_data[local_start] + value;
        local_data[local_start] := value;
        local_start := (local_start + 1) MOD 100;
    END_IF;
ELSIF tmp_trig.Q THEN
    IF local_count < 100 THEN
        local_data[local_count] := value;
        local_count := local_count + 1;
        local_sum_all := local_sum_all + value;
    ELSE
        local_sum_all := local_sum_all - local_data[local_start] + value;
        local_data[local_start] := value;
        local_start := (local_start + 1) MOD 100;
    END_IF;
END_IF;

local_avg_sum := local_sum_all;

IF local_count > windowSize THEN
    FOR tmp_i := 0 TO (local_count - windowSize - 1) DO
        tmp_idx := (local_start + tmp_i) MOD 100;
        local_avg_sum := local_avg_sum - local_data[tmp_idx];
    END_FOR;
END_IF;

local_effective := local_count;
IF local_effective > windowSize THEN
    local_effective := windowSize;
END_IF;

IF local_effective > 0 THEN
    average := local_avg_sum / INT_TO_LREAL(local_effective);
ELSE
    average := 0.0;
END_IF;

windowSizeReached := local_count >= windowSize;

program.implementation:
IF NOT testComplete THEN
CASE step OF
0:probe(cyclicExecution:=TRUE,trigger:=FALSE,value:=LREAL#7.0,windowSize:=2,reset:=TRUE);tmp_expected:=0.0;
1:probe(cyclicExecution:=TRUE,trigger:=FALSE,value:=LREAL#9.0,windowSize:=2,reset:=FALSE);tmp_expected:=9.0;
2:probe(cyclicExecution:=TRUE,trigger:=FALSE,value:=LREAL#13.0,windowSize:=2,reset:=TRUE);tmp_expected:=0.0;
3:probe(cyclicExecution:=TRUE,trigger:=FALSE,value:=LREAL#5.0,windowSize:=2,reset:=FALSE);tmp_expected:=5.0;
END_CASE;
IF (probe.average<>tmp_expected) OR probe.windowSizeReached OR probe.error OR (probe.status<>WORD#0) THEN
 IF testPassed THEN firstFailedStep:=step;END_IF;
 testPassed:=FALSE;
END_IF;
IF step=3 THEN testComplete:=TRUE;ELSE step:=step+1;END_IF;
END_IF;
